package deployment_image_pull_failure

import (
	"context"
	appsv1 "k8s.io/api/apps/v1"
	corev1 "k8s.io/api/core/v1"
	"sdo.dev/operator/sdk/program"
)

type Program struct{}

func (Program) Spec() program.ProgramSpec {
	return program.ProgramSpec{ID: "deployment-image-pull-failure", Params: []program.ParamSpec{{Name: "deployment", Kind: "Deployment", Required: true}}}
}

// failedPull requires a current-image pod owned through this Deployment's
// ReplicaSet. Old rollouts, startup waits, and application crashes do not match.
func failedPull(d appsv1.Deployment, pods []corev1.Pod, sets []appsv1.ReplicaSet) bool {
	desired := int32(1)
	if d.Spec.Replicas != nil {
		desired = *d.Spec.Replicas
	}
	if desired < 1 || d.Status.AvailableReplicas >= desired {
		return false
	}
	for _, p := range pods {
		if p.Namespace != d.Namespace || p.DeletionTimestamp != nil {
			continue
		}
		owned := false
		for _, po := range p.OwnerReferences {
			if po.Kind != "ReplicaSet" || po.Controller == nil || !*po.Controller {
				continue
			}
			for _, rs := range sets {
				if rs.Namespace != d.Namespace || rs.Name != po.Name {
					continue
				}
				for _, ro := range rs.OwnerReferences {
					if ro.Kind == "Deployment" && ro.Name == d.Name && ro.Controller != nil && *ro.Controller {
						owned = true
					}
				}
			}
		}
		if !owned {
			continue
		}
		for _, c := range d.Spec.Template.Spec.Containers {
			for _, pc := range p.Spec.Containers {
				if pc.Name != c.Name || pc.Image != c.Image {
					continue
				}
				for _, s := range p.Status.ContainerStatuses {
					if s.Name != c.Name || s.Ready || s.ImageID != "" || s.State.Waiting == nil {
						continue
					}
					if s.State.Waiting.Reason == "ImagePullBackOff" || s.State.Waiting.Reason == "ErrImagePull" {
						return true
					}
				}
			}
		}
	}
	return false
}
func (Program) Diagnose(_ context.Context, v program.ReadView, b program.Bindings) (program.Verdict, error) {
	ref := b["deployment"]
	for _, d := range v.Deployments() {
		if d.Namespace != ref.Namespace || d.Name != ref.Name {
			continue
		}
		if failedPull(d, v.Pods(), v.ReplicaSets()) {
			return program.Verdict{Result: program.Match, Evidence: []program.Evidence{{Resource: ref, Fact: "unavailable deployment with current-image pull failure", Observed: "owned pod waiting in ImagePullBackOff or ErrImagePull without an image ID", Expected: "available replicas and pullable image"}}}, nil
		}
		return program.Verdict{Result: program.NoMatch}, nil
	}
	return program.Verdict{Result: program.Unknown}, nil
}

package deployment_image_pull_failure

import (
	"context"
	appsv1 "k8s.io/api/apps/v1"
	corev1 "k8s.io/api/core/v1"
	metav1 "k8s.io/apimachinery/pkg/apis/meta/v1"
	"sdo.dev/operator/sdk"
	"sdo.dev/operator/sdk/program"
	"testing"
	"time"
)

type view struct {
	program.ReadView
	ds []appsv1.Deployment
	ps []corev1.Pod
	rs []appsv1.ReplicaSet
}

func (v view) Deployments() []appsv1.Deployment { return v.ds }
func (v view) Pods() []corev1.Pod               { return v.ps }
func (v view) ReplicaSets() []appsv1.ReplicaSet { return v.rs }
func fixture() view {
	yes := true
	replicas := int32(1)
	d := appsv1.Deployment{ObjectMeta: metav1.ObjectMeta{Name: "workload", Namespace: "test"}, Spec: appsv1.DeploymentSpec{Replicas: &replicas, Template: corev1.PodTemplateSpec{Spec: corev1.PodSpec{Containers: []corev1.Container{{Name: "app", Image: "registry/new:broken"}}}}}}
	rs := appsv1.ReplicaSet{ObjectMeta: metav1.ObjectMeta{Name: "rollout", Namespace: "test", OwnerReferences: []metav1.OwnerReference{{Kind: "Deployment", Name: d.Name, Controller: &yes}}}}
	p := corev1.Pod{ObjectMeta: metav1.ObjectMeta{Name: "instance", Namespace: "test", OwnerReferences: []metav1.OwnerReference{{Kind: "ReplicaSet", Name: rs.Name, Controller: &yes}}}, Spec: d.Spec.Template.Spec, Status: corev1.PodStatus{ContainerStatuses: []corev1.ContainerStatus{{Name: "app", State: corev1.ContainerState{Waiting: &corev1.ContainerStateWaiting{Reason: "ImagePullBackOff"}}}}}}
	return view{ds: []appsv1.Deployment{d}, ps: []corev1.Pod{p}, rs: []appsv1.ReplicaSet{rs}}
}
func TestSignatureAndNearMisses(t *testing.T) {
	tests := []struct {
		name   string
		change func(*view)
		match  bool
	}{
		{"confirmed-backoff", func(v *view) {}, true},
		{"confirmed-pull-error", func(v *view) { v.ps[0].Status.ContainerStatuses[0].State.Waiting.Reason = "ErrImagePull" }, true},
		{"startup-is-not-pull-failure", func(v *view) { v.ps[0].Status.ContainerStatuses[0].State.Waiting.Reason = "ContainerCreating" }, false},
		{"crash-is-not-pull-failure", func(v *view) { v.ps[0].Status.ContainerStatuses[0].State.Waiting.Reason = "CrashLoopBackOff" }, false},
		{"healthy-deployment", func(v *view) { v.ds[0].Status.AvailableReplicas = 1 }, false},
		{"scaled-to-zero", func(v *view) { *v.ds[0].Spec.Replicas = 0 }, false},
		{"old-image", func(v *view) { v.ps[0].Spec.Containers = []corev1.Container{{Name: "app", Image: "registry/old:tag"}} }, false},
		{"unrelated-rollout", func(v *view) { v.rs[0].OwnerReferences[0].Name = "other" }, false},
		{"different-namespace", func(v *view) { v.ps[0].Namespace = "other" }, false},
		{"deleted-pod", func(v *view) { stamp := metav1.NewTime(time.Unix(1, 0)); v.ps[0].DeletionTimestamp = &stamp }, false},
		{"already-pulled", func(v *view) { v.ps[0].Status.ContainerStatuses[0].ImageID = "sha256:abc" }, false},
		{"ready-container", func(v *view) { v.ps[0].Status.ContainerStatuses[0].Ready = true }, false},
	}
	b := program.Bindings{"deployment": sdk.ObjectRef{APIVersion: "apps/v1", Kind: "Deployment", Namespace: "test", Name: "workload"}}
	for _, tt := range tests {
		t.Run(tt.name, func(t *testing.T) {
			v := fixture()
			tt.change(&v)
			got, err := (Program{}).Diagnose(context.Background(), v, b)
			if err != nil || (got.Result == program.Match) != tt.match {
				t.Fatalf("got %+v, %v; want %v", got, err, tt.match)
			}
			plan, err := (Program{}).Mitigate(context.Background(), v, b)
			if err != nil {
				t.Fatal(err)
			}
			if tt.match && len(plan.Actions) != 1 {
				t.Fatal("missing source reconciliation")
			}
			if !tt.match && len(plan.Actions) != 0 {
				t.Fatal("near miss received repair")
			}
		})
	}
}
func TestRequiredBinding(t *testing.T) {
	if err := program.ValidateBindings(Program{}.Spec(), nil); err == nil {
		t.Fatal("accepted missing deployment")
	}
}

package deployment_image_pull_failure

import (
	"context"
	"sdo.dev/operator/sdk/program"
)

func (p Program) Mitigate(ctx context.Context, v program.ReadView, b program.Bindings) (program.Plan, error) {
	verdict, err := p.Diagnose(ctx, v, b)
	if err != nil || verdict.Result != program.Match {
		return program.Plan{}, err
	}
	return program.Plan{Actions: []program.Action{program.ReconcileFromSource{Ref: b["deployment"]}}}, nil
}
